mapper.update:
UPDATE emp55_benefit_info
   SET emp55_benefit_cd      = #{req.benefitCode},
       emp55_issue_link_cd   = #{req.issueLinkCode},
       emp55_expense_link_cd = #{req.expenseLinkCode},
       emp55_account_cd      = #{req.accountCode},
       emp55_un_use_yn       = #{req.unUseYn}
 WHERE emp55_benefit_info_id = #{req.benefitInfoId}
   AND emp55_company_id      = #{companyId}

mapper.delete:
DELETE FROM emp55_benefit_info
 WHERE emp55_company_id = #{companyId}
   AND emp55_benefit_info_id IN
#{id}
